import json
from fractions import Fraction

# Original function: (m*x + b)*ln(x) - a*(x - r).
m, b, r = map(Fraction, (1, 1, 1))

# Product-rule differentiation:
# f'(x) = m*ln(x) + m + b/x - a
# f''(x) = (m*x - b)/x**2
f_at_one = Fraction(0)
derivative_offset_at_one = m + b
second_derivative_root = b / m

if not (r == 1 and m > 0 and second_derivative_root == 1):
    print("UNSUPPORTED")
else:
    a_part_one = Fraction(1)
    slope = derivative_offset_at_one - a_part_one
    intercept = f_at_one - slope
    upper_bound = derivative_offset_at_one

    def exact(q):
        return str(q.numerator) if q.denominator == 1 else str(q)

    def line(s, t):
        x_term = "x" if s == 1 else (
            "-x" if s == -1 else exact(s) + "*x"
        )
        if t == 0:
            return "y = " + x_term
        return "y = " + x_term + (" + " if t > 0 else " - ") + exact(abs(t))

    answer = {
        "final_answer": (
            "(1) " + line(slope, intercept) +
            "; (2) a in (-infinity, " + exact(upper_bound) + "]."
        ),
        "evidence": {
            "f(1)": exact(f_at_one),
            "f'(1)": exact(derivative_offset_at_one) + " - a",
            "f''(x)": "(x - 1)/x^2 > 0 for x > 1",
            "sufficiency": (
                "For a <= " + exact(upper_bound) +
                ", f'(1) >= 0. Since f''(x) > 0 for x > 1, "
                "f'(x) > 0 there, so f(x) > f(1) = 0."
            ),
            "necessity": (
                "For a > " + exact(upper_bound) +
                ", f'(1) < 0. Continuity of f' makes f(x) < 0 "
                "for x sufficiently close to 1 from the right."
            )
        }
    }
    print(json.dumps(answer, separators=(",", ":")))
