import json
from fractions import Fraction as F

# F(x,y,u,p,q) = pq-u:
# x' = q, y' = p, u' = 2pq, p' = p, q' = q.
# On the initial curve q = du/dtau = 2*tau.
# For tau != 0, pq = tau^2 gives p = tau/2.
# Normalize x,y by tau and u by tau^2, and put t = exp(s).

def clean(poly):
    return {k: F(v) for k, v in poly.items() if v}

def derivative_s(poly):
    return clean({k: k * v for k, v in poly.items()})

def multiply(a, b):
    result = {}
    for i, ai in a.items():
        for j, bj in b.items():
            result[i + j] = result.get(i + j, F(0)) + ai * bj
    return clean(result)

def scale(poly, factor):
    return clean({k: factor * v for k, v in poly.items()})

def initial_value(poly):
    return sum(poly.values(), F(0))  # s=0 means t=1

q0 = F(2)
u0 = F(1)
p0 = u0 / q0

derived = (
    clean({1: q0, 0: -q0}),
    clean({1: p0, 0: F(1) - p0}),
    clean({2: u0}),
)

options = [
    ({1: F(3), 0: F(-3)},
     {-1: F(1, 2), 0: F(1, 2)},
     {-2: F(1)}),
    ({1: F(2), 0: F(-2)},
     {2: F(2), 0: F(-1)},
     {0: F(1, 2), -2: F(1, 2)}),
    ({1: F(2), 0: F(-2)},
     {1: F(1, 2), 0: F(1, 2)},
     {2: F(1)}),
    ({-1: F(1), 0: F(-1)},
     {-1: F(-2), 0: F(3)},
     {-2: F(2), 0: F(-1)}),
]

matches = []
checks = []
for number, raw in enumerate(options, 1):
    x, y, u = map(clean, raw)
    q = derivative_s(x)
    p = derivative_s(y)
    valid = (
        [initial_value(v) for v in (x, y, u)] == [0, 1, 1]
        and derivative_s(p) == p
        and derivative_s(q) == q
        and multiply(p, q) == u
        and derivative_s(u) == scale(u, 2)
        and (x, y, u) == derived
    )
    checks.append(valid)
    if valid:
        matches.append(number)

evidence = {
    "charpit": ["x'=q", "y'=p", "u'=2pq", "p'=p", "q'=q"],
    "initial_p_over_tau": str(p0),
    "initial_q_over_tau": str(q0),
    "derived_coefficients_in_exp_s": {
        name: {str(k): str(v) for k, v in sorted(poly.items())}
        for name, poly in zip(("x/tau", "y/tau", "u/tau^2"), derived)
    },
    "option_checks": checks,
    "tau_zero": "The selected family extends to the constant curve (0,0,0).",
}

answer = f"Option {matches[0]}" if len(matches) == 1 else "UNSUPPORTED"
print(json.dumps({"final_answer": answer, "evidence": evidence},
                 separators=(",", ":")))
