import json
import unicodedata
from itertools import product
from functools import lru_cache

data = [
    ("tmi’gn", "dəmīgən"),
    ("an’stawteg", "anəstawtek"),
    ("gjiansale’wit", "əkciansalēwit"),
    ("mgumie’jo’tlatl", "əmkumiējōdəladəl"),
    ("amqwanji’j", "amxʷancīc"),
    ("e’jnt", "ējənt"),
    ("tplutaqan", "ətpəludaɣan"),
    ("ge’gwising", "gēgʷisink"),
    ("lnu’sgw", "lənūskw"),
    ("g’p’ta’q", "gəbədāx"),
    ("epsaqtejg", "epsaxteck"),
]

vowels = set("aeiouAEIOUə")
correspondences = {
    "a": {"a"}, "e": {"e"}, "i": {"i"},
    "o": {"o"}, "u": {"u"},
    "A": {"A"}, "E": {"E"}, "I": {"I"},
    "O": {"O"}, "U": {"U"},
    "t": {"t", "d"}, "p": {"p", "b"},
    "g": {"g", "k"}, "q": {"x", "ɣ"},
    "j": {"j", "c"}, "m": {"m"}, "n": {"n"},
    "l": {"l"}, "s": {"s"}, "w": {"w"},
    "'": {"ə"},
}

def spelling_tokens(text):
    text = text.replace("’", "'")
    result = []
    for char in text:
        if char == "'" and result and result[-1] in "aeiou":
            result[-1] = result[-1].upper()
        else:
            result.append(char)
    return tuple(result)

def sound_tokens(text):
    result = []
    for char in unicodedata.normalize("NFD", text):
        if char == "\u0304":
            result[-1] = result[-1].upper()
        elif char == "ʷ":
            result.append("w")
        else:
            result.append(char)
    return tuple(result)

def align(source, target):
    @lru_cache(None)
    def visit(i, j):
        if i == len(source) and j == len(target):
            return ((),)
        solutions = []
        if (i < len(source) and j < len(target)
                and target[j] in correspondences[source[i]]):
            for tail in visit(i + 1, j + 1):
                solutions.append((("match", i, target[j]),) + tail)
        if j < len(target) and target[j] == "ə":
            for tail in visit(i, j + 1):
                solutions.append((("insert", i, "ə"),) + tail)
        return tuple(solutions)
    return visit(0, 0)

def main():
    examples = [
        (spelling_tokens(word), sound_tokens(sound))
        for word, sound in data
    ]
    insertion_contexts = set()
    observations = []

    for source, target in examples:
        alignments = align(source, target)
        if len(alignments) != 1:
            return {"final_answer": "UNSUPPORTED"}
        for kind, index, sound in alignments[0]:
            if kind == "insert":
                left = source[index - 1] if index else "#"
                right = source[index] if index < len(source) else "#"
                insertion_contexts.add((left, right))
            else:
                observations.append((source, index, sound))

    # Stops are voiced in a vowel/sonorant environment unless
    # immediately preceded by another consonant.
    sonorants = set("mnlw")
    learned_outputs = {}

    def environment(source, index):
        previous = source[index - 1] if index else "#"
        following = source[index + 1] if index + 1 < len(source) else "#"
        previous_is_consonant = previous not in vowels | {"#", "'"}
        following_supports_voicing = following in vowels | sonorants | {"'"}
        return not previous_is_consonant and following_supports_voicing

    for source, index, sound in observations:
        token = source[index]
        key = (token, environment(source, index)) if token in "tpgqj" else (token,)
        if key in learned_outputs and learned_outputs[key] != sound:
            return {"final_answer": "UNSUPPORTED"}
        learned_outputs[key] = sound

    def pronounce(source):
        output = []
        for index, token in enumerate(source):
            left = source[index - 1] if index else "#"
            if (left, token) in insertion_contexts:
                output.append("ə")
            key = (token, environment(source, index)) if token in "tpgqj" else (token,)
            if key not in learned_outputs:
                return None
            output.append(learned_outputs[key])
        return tuple(output)

    if not all(pronounce(source) == target for source, target in examples):
        return {"final_answer": "UNSUPPORTED"}

    target = sound_tokens("alaptək")
    inverse_options = []
    for sound in target:
        choices = [
            token for token, sounds in correspondences.items()
            if sound in sounds
        ]
        if sound == "ə":
            choices.append("")  # Test automatic insertion as well.
        inverse_options.append(choices)

    answers = set()
    tested = 0
    for selection in product(*inverse_options):
        source = tuple(token for token in selection if token)
        tested += 1
        if pronounce(source) == target:
            word = "".join(
                token.lower() + "’" if token in "AEIOU"
                else "’" if token == "'" else token
                for token in source
            )
            answers.add(word)

    if len(answers) != 1:
        return {"final_answer": "UNSUPPORTED"}

    return {
        "final_answer": next(iter(answers)),
        "evidence": {
            "examples_verified": len(examples),
            "inverse_candidates_tested": tested,
            "matching_candidates": len(answers),
            "schwa": "Explicit apostrophe; automatic insertion does not apply before g."
        }
    }

print(json.dumps(main(), ensure_ascii=False, separators=(",", ":")))
