from fractions import Fraction as Q

# Exact Laurent polynomials in (tau, t), where t = exp(s) > 0.
def poly(*terms):
    result = {}
    for coefficient, a, b in terms:
        key = (a, b)
        result[key] = result.get(key, Q(0)) + Q(coefficient)
    return {k: v for k, v in result.items() if v}

def add(*polys):
    result = {}
    for P in polys:
        for k, v in P.items():
            result[k] = result.get(k, Q(0)) + v
    return {k: v for k, v in result.items() if v}

def scale(P, c):
    return {k: v * c for k, v in P.items() if v * c}

def mul(P, R):
    result = {}
    for (a, b), v in P.items():
        for (c, d), w in R.items():
            k = (a + c, b + d)
            result[k] = result.get(k, Q(0)) + v * w
    return {k: v for k, v in result.items() if v}

def ds(P):
    return {(a, b): v * b for (a, b), v in P.items() if b}

def dtau(P):
    return {(a - 1, b): v * a for (a, b), v in P.items() if a}

def evaluate(P, tau, t):
    return sum((v * Q(tau)**a * Q(t)**b
                for (a, b), v in P.items()), Q(0))

def at_initial(P):
    result = {}
    for (a, b), v in P.items():
        result[a] = result.get(a, Q(0)) + v
    return {a: v for a, v in result.items() if v}

options = [
    (
        poly((3, 1, 1), (-3, 1, 0)),
        poly((Q(1, 2), 1, -1), (Q(1, 2), 1, 0)),
        poly((1, 2, -2)),
    ),
    (
        poly((2, 1, 1), (-2, 1, 0)),
        poly((2, 1, 2), (-1, 1, 0)),
        poly((Q(1, 2), 2, 0), (Q(1, 2), 2, -2)),
    ),
    (
        poly((2, 1, 1), (-2, 1, 0)),
        poly((Q(1, 2), 1, 1), (Q(1, 2), 1, 0)),
        poly((1, 2, 2)),
    ),
    (
        poly((1, 1, -1), (-1, 1, 0)),
        poly((-2, 1, -1), (3, 1, 0)),
        poly((2, 2, -2), (-1, 2, 0)),
    ),
]

# F = pq-u. Charpit's equations:
# x_s=q, y_s=p, u_s=2pq, p_s=p, q_s=q.
# Initial compatibility gives q(0)=2*tau.
# For tau != 0, pq=tau^2 gives p(0)=tau/2.
p = poly((Q(1, 2), 1, 1))
q = poly((2, 1, 1))

assert ds(p) == p and ds(q) == q
valid = []
for number, (x, y, u) in enumerate(options, 1):
    initial_ok = (
        at_initial(x) == {}
        and at_initial(y) == {1: Q(1)}
        and at_initial(u) == {2: Q(1)}
    )
    residuals = [
        add(ds(x), scale(q, -1)),
        add(ds(y), scale(p, -1)),
        add(ds(u), scale(mul(p, q), -2)),
        add(mul(p, q), scale(u, -1)),
    ]
    charpit_ok = not any(residuals)
    print("Option", number,
          "initial condition:", initial_ok,
          "exact Charpit identities:", charpit_ok)
    if initial_ok and charpit_ok:
        valid.append(number)

print("Expected option(s):", valid)
print("Expected curves: x=2*tau*(exp(s)-1), "
      "y=tau*(exp(s)+1)/2, u=tau^2*exp(2*s)")
print("The expected curves also satisfy all identities at tau=0.")

# Independent exact counterexample for the submitted option:
# Recover p=u_x and q=u_y by the chain rule on its parametrized surface.
x, y, u = options[0]
tau, t = Q(1), Q(2)  # s = log(2)
xs, ys, us = (evaluate(ds(P), tau, t) for P in (x, y, u))
xt, yt, ut = (evaluate(dtau(P), tau, t) for P in (x, y, u))
jacobian = xs * yt - ys * xt
assert jacobian != 0
px = (us * yt - ys * ut) / jacobian
qy = (xs * ut - us * xt) / jacobian
uv = evaluate(u, tau, t)
residual = px * qy - uv

print("Submitted option 1, at tau=1 and exp(s)=2:")
print("Jacobian =", jacobian)
print("u_x =", px, "u_y =", qy, "u =", uv)
print("u_x*u_y-u =", residual)
print("This exact counterexample disproves the submitted answer; "
      "the expected option was verified by polynomial identities.")
print("CHECK FAIL" if residual != 0 and valid == [3] else "CHECK UNKNOWN")
