import itertools
import json

groups = {
    "opinion": "silly terrible wonderful lovely repulsive ridiculous mysterious nice awful good",
    "size": "medium-size massive little huge large tiny big small enormous midsize normal-size",
    "age": "new archaic old-fashioned ancient brand-new old",
    "shape": "prismlike rectangular pyramidal circular square triangular spherical",
    "color": "yellow violet aqua crimson green maroon magenta cyan brown pink blue red indigo gray white black",
    "origin": "egyptian chinese turkish vietnamese german bangladeshi mexican russian iranian ethiopian filipino thai indonesian",
    "material": "plastic wood wool iron fiberglass cardboard glass leather paper cloth",
    "purpose": "typing whittling exercise walking smoking hiking car snorkeling drinking driving eating",
}
category = {
    word: group
    for group, words in groups.items()
    for word in words.split()
}

givens = """
yellow ruler;silly violet fork;silly aqua key;prismlike sunglasses;
new ruler;archaic apple;terrible stapler;crimson dog;medium-size spoon;
old-fashioned hammer;prismlike pen;typing ruler;new guitar;
plastic egyptian necklace;wonderful shoe;whittling ruler;lovely piano;
new scissors;whittling saw;lovely aqua necklace;massive spoon;
ancient exercise candle;silly brown jar;rectangular stapler;
prismlike bird;walking car;wood chinese hat;smoking apple;
little square plate;old-fashioned typing flower pot;repulsive canvas;
hiking hat;wool speaker;turkish old green box;huge dog;pyramidal lamp;
prismlike saw;circular flower pot;maroon chair;egyptian jar;
magenta bird;hiking spoon;iron sofa;large hat;tiny speaker;
fiberglass vietnamese bottle;cyan hat;old-fashioned car key;
new smoking toolbox;big triangular earring;terrible hat;maroon piano;
ridiculous indigo sunglasses;archaic snorkeling bicycle;cardboard sofa;
lovely fork;circular bowl;pink guitar;medium-size car;large fork;
blue candle;triangular plate;rectangular spoon;huge scissors;
massive knife;small circular pencil;small spherical key;
ancient drinking candle;new drill;new drinking bowl;
triangular sunglasses;brand-new cup;mysterious hammer;
enormous triangular calculator;whittling stapler;square bed;
cardboard typing lovely flower pot;german piano;
glass bangladeshi watch;wool hammer;triangular house;
iron mexican vase;massive rectangular screwdriver;prismlike necklace;
nice red flower pot;old-fashioned pen;awful magenta spoon;russian bird;
crimson flower pot;tiny pyramidal vase;good key;leather iranian box;
repulsive gray ring;ethiopian knife;brown bag;midsize circular chair;
snorkeling trash can;new whittling fire extinguisher
""".strip().split(";")

options = {
    "A": "circular large old-fashioned driving good black sofa",
    "B": "wood filipino ancient smoking awful violet tiny prismlike fork",
    "C": "prismlike brand-new smoking ridiculous violet iranian paper bed",
    "D": "old drinking terrible white normal-size square wrench",
    "E": "cloth thai brand-new eating good blue plate",
    "F": "fiberglass indonesian brand-new smoking wonderful cyan massive bottle",
    "G": "big rectangular archaic smoking terrible yellow vase",
    "H": "thai old drinking nice green massive pyramidal clock",
    "I": "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
    "J": "spherical little ancient walking good indigo bangladeshi jar",
}

def adjective_categories(phrase):
    result = []
    for word in phrase.split():
        if word not in category:
            break
        result.append(category[word])
    return result

assert len(givens) == 98
constraints = set()
for phrase in givens:
    sequence = adjective_categories(phrase)
    constraints.update(
        (sequence[i], sequence[j])
        for i in range(len(sequence))
        for j in range(i + 1, len(sequence))
    )

option_sequences = {
    letter: adjective_categories(phrase)
    for letter, phrase in options.items()
}

# Exhaustively enumerate every total category order consistent with the
# original examples. Do not choose an unprovided ordering between chains.
answer_sets = set()
valid_order_count = 0
for order in itertools.permutations(groups):
    rank = {group: index for index, group in enumerate(order)}
    if not all(rank[a] < rank[b] for a, b in constraints):
        continue
    valid_order_count += 1
    correct = []
    for letter, sequence in option_sequences.items():
        if all(rank[a] < rank[b] for a, b in zip(sequence, sequence[1:])):
            correct.append(letter)
    answer_sets.add("".join(correct) or "K")

if len(answer_sets) == 1:
    final_answer = next(iter(answer_sets))
else:
    final_answer = "UNSUPPORTED"

possible = sorted(set().union(*(set(s) for s in answer_sets))) if answer_sets else []
forced = sorted(set.intersection(*(set(s) for s in answer_sets))) if answer_sets else []

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "consistent_total_orders": valid_order_count,
        "distinct_answer_sets": sorted(answer_sets),
        "forced_choices": "".join(forced),
        "possible_choices": "".join(possible),
        "reason": (
            "The givens do not determine the relative placement of the "
            "size/shape chain and the other adjective categories."
            if len(answer_sets) > 1 else
            "All consistent category orders give the same answer."
        )
    }
}, separators=(",", ":")))
