import re
import math
import json
from fractions import Fraction

path = """M 24.38698,-19.9365 L 29.3405,-17.62663
M 0.0,7.0 L 0.0,5.46
M 10.35209,0.0 L 10.35209,-7.0986
M 20.49493,-28.84999 L 17.75636,-22.97711
M 20.49493,-21.75139 L 24.38698,-19.9365
M 18.29129,-17.02568 L 20.49493,-21.75139
M 17.75636,-22.97711 L 15.16487,-17.41963
M 10.35209,-7.0986 L 0.0,-7.0986
M 22.10067,8.68911 L 19.34832,10.61633
M 2.5205,-5.64339 L 6.14757,-3.5493
M 10.35209,-4.68508 L 10.35209,0.0
M 10.35209,-7.0986 L 10.35209,-4.68508
M 20.49493,-25.44266 L 20.49493,-28.84999
M 0.0,-7.0986 L 2.5205,-5.64339
M 6.14757,-3.5493 L 2.33608,-1.34873
M 24.85302,6.76189 L 22.10067,8.68911
M 15.93065,-11.96326 L 17.25429,-14.80182
M 20.49493,-21.75139 L 20.49493,-25.44266
M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912
M 10.35209,1.96 L 10.35209,3.3712
M 0.0,5.46 L 0.0,0.0
M 4.03732,0.0 L 10.35209,0.0
M 10.35209,7.0 L 7.55703,7.0
M 10.35209,0.0 L 15.93065,-11.96326
M 10.35209,3.3712 L 10.35209,7.0
M 2.33608,-1.34873 L 0.0,0.0
M 34.99586,-14.98949 L 24.85302,6.76189
M 15.16487,-17.41963 L 10.35209,-7.0986
M 11.74658,15.93912 L 11.17484,9.40408
M 0.0,0.0 L 4.03732,0.0
M 11.17484,9.40408 L 10.79637,5.0782
M 29.3405,-17.62663 L 34.99586,-14.98949
M 10.35209,0.0 L 10.35209,1.96
M 10.79637,5.0782 L 10.35209,0.0
M 7.55703,7.0 L 0.0,7.0
M 17.25429,-14.80182 L 18.29129,-17.02568"""

# Parse the supplied decimal coordinates exactly.
vertices = []
indices = {}
edges = set()
previous = None
for command, x, y in re.findall(
    r"([ML])\s+(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)", path
):
    point = (Fraction(x), Fraction(y))
    if point not in indices:
        indices[point] = len(vertices)
        vertices.append(point)
    current = indices[point]
    if command == "L":
        edges.add(tuple(sorted((previous, current))))
    previous = current

points = [(float(x), float(y)) for x, y in vertices]
adjacency = [set() for _ in points]
for a, b in edges:
    adjacency[a].add(b)
    adjacency[b].add(a)

# Rounding tolerance: far smaller than any actual angle or separation here.
ANGLE_EPS = 1e-5
DIST_EPS = 5e-5

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def norm(a):
    return math.hypot(*a)

def parallel(a, b):
    return abs(cross(a, b)) <= ANGLE_EPS * norm(a) * norm(b)

def perpendicular(a, b):
    return abs(dot(a, b)) <= ANGLE_EPS * norm(a) * norm(b)

def simplify(poly):
    poly = poly[:]
    changed = True
    while changed and len(poly) > 3:
        changed = False
        for i in range(len(poly)):
            u = sub(poly[i], poly[i - 1])
            v = sub(poly[(i + 1) % len(poly)], poly[i])
            if parallel(u, v) and dot(u, v) > 0:
                del poly[i]
                changed = True
                break
    return poly

def on_segment(p, a, b):
    v = sub(b, a)
    w = sub(p, a)
    return (
        abs(cross(v, w)) <= DIST_EPS * max(1.0, norm(v))
        and -DIST_EPS <= dot(w, v) / norm(v) <= norm(v) + DIST_EPS
    )

def inside(p, poly):
    if any(on_segment(p, a, poly[(i + 1) % len(poly)])
           for i, a in enumerate(poly)):
        return False
    result = False
    for i, a in enumerate(poly):
        b = poly[(i + 1) % len(poly)]
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if x > p[0]:
                result = not result
    return result

def proper_crossing(a, b, c, d):
    u, v = sub(b, a), sub(d, c)
    s1, s2 = cross(u, sub(c, a)), cross(u, sub(d, a))
    t1, t2 = cross(v, sub(a, c)), cross(v, sub(b, c))
    eps_u = DIST_EPS * max(1.0, norm(u))
    eps_v = DIST_EPS * max(1.0, norm(v))
    return (
        ((s1 > eps_u and s2 < -eps_u) or
         (s2 > eps_u and s1 < -eps_u))
        and
        ((t1 > eps_v and t2 < -eps_v) or
         (t2 > eps_v and t1 < -eps_v))
    )

# Confirm that graph cycles suffice: there are no unrepresented crossings.
for a, b in edges:
    for c, d in edges:
        if proper_crossing(points[a], points[b], points[c], points[d]):
            print("UNSUPPORTED")
            raise SystemExit

# Exhaustively enumerate all undirected simple cycles.
cycles = set()
for start in range(len(points)):
    def visit(chain, used):
        last = chain[-1]
        for nxt in adjacency[last]:
            if nxt == start:
                if len(chain) >= 3:
                    forward = tuple(chain)
                    backward = (start,) + tuple(reversed(chain[1:]))
                    cycles.add(min(forward, backward))
            elif nxt > start and nxt not in used:
                visit(chain + [nxt], used | {nxt})
    visit([start], {start})

def classify(poly):
    n = len(poly)
    vectors = [
        sub(poly[(i + 1) % n], poly[i]) for i in range(n)
    ]
    lengths = [norm(v) for v in vectors]
    turns = [
        cross(vectors[i], vectors[(i + 1) % n]) for i in range(n)
    ]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    equal_sides = max(lengths) - min(lengths) <= ANGLE_EPS * max(lengths)

    if n == 3:
        return 4 if any(
            perpendicular(vectors[i], vectors[(i + 1) % n])
            for i in range(n)
        ) else 3
    if n == 4:
        opposite = [
            parallel(vectors[0], vectors[2]),
            parallel(vectors[1], vectors[3]),
        ]
        right = all(
            perpendicular(vectors[i], vectors[(i + 1) % n])
            for i in range(n)
        )
        if all(opposite):
            return (2 if equal_sides else 1) if right else 5
        if sum(opposite) == 1:
            return 6
    if n in (5, 6):
        cosines = [
            dot(vectors[i], vectors[(i + 1) % n])
            / (lengths[i] * lengths[(i + 1) % n])
            for i in range(n)
        ]
        regular = (
            convex and equal_sides
            and max(cosines) - min(cosines) <= ANGLE_EPS
        )
        if n == 5:
            return 9 if regular else (7 if convex else 8)
        if regular:
            return 10
    return None

evidence = {}
for cycle in sorted(cycles):
    poly = simplify([points[i] for i in cycle])
    # Reject polygons with additional drawn lines in their interiors.
    if any(
        inside(((points[a][0] + points[b][0]) / 2,
                (points[a][1] + points[b][1]) / 2), poly)
        for a, b in edges
    ):
        continue
    shape = classify(poly)
    if shape is not None:
        evidence.setdefault(shape, [
            [round(x, 5), round(y, 5)] for x, y in poly
        ])

