    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
matches = [letter for letter, shapes in options.items()
           if shapes == set(evidence)]
if len(matches) != 1:
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": "(" + matches[0] + ")",
        "evidence": {
            "shape_ids": sorted(evidence),
            "corner_coordinates": {
                str(k): evidence[k] for k in sorted(evidence)
            },
            "method": "Exhaustive simple-cycle enumeration; collinear segments merged; interior drawn lines excluded."
        }
