# givens constrains the truth values of these four additional claims.
models = list(itertools.product((False, True), repeat=len(options)))
counterexamples = {
    label: sum(not model[i] for model in models)
    for i, label in enumerate(options)
}
necessary = [
    label for label, count in counterexamples.items() if count == 0
]

print(json.dumps({
    "final_answer": necessary[0] if len(necessary) == 1 else "UNSUPPORTED",
    "evidence": {
        "models_checked": len(models),
        "countermodels_per_option": counterexamples,
        "limitation": (
            "The explanation alone supplies no implication establishing "
            "any listed claim as necessary. In particular, a prohibition "
            "does not logically imply that the prohibited food existed."
        )
    }
}, separators=(",", ":")))
