import json
from fractions import Fraction as F

s, q = F(9), F(14)
D = s * s - 3 * q

# Exact arithmetic in Q(sqrt(D)); a pair (a,b) denotes a+b*sqrt(D).
def scalar(a):
    return (F(a), F(0))

def add(u, v):
    return (u[0] + v[0], u[1] + v[1])

def neg(u):
    return (-u[0], -u[1])

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    return (u[0]*v[0] + D*u[1]*v[1],
            u[0]*v[1] + u[1]*v[0])

def div(u, v):
    norm = v[0]*v[0] - D*v[1]*v[1]
    if norm == 0:
        raise ArithmeticError("Zero denominator")
    w = mul(u, (v[0], -v[1]))
    return (w[0]/norm, w[1]/norm)

def sign(u):
    a, b = u
    if b == 0:
        return (a > 0) - (a < 0)
    if a == 0:
        return (b > 0) - (b < 0)
    if (a > 0) == (b > 0):
        return 1 if a > 0 else -1
    delta = a*a - D*b*b
    if delta == 0:
        return 0
    return ((a > 0) - (a < 0)) * ((delta > 0) - (delta < 0))

def text(u):
    a, b = u
    if b == 0:
        return str(a)
    if a == 0:
        return f"({b})*sqrt({D})"
    op = "+" if b > 0 else "-"
    return f"({a}) {op} ({abs(b)})*sqrt({D})"

try:
    root = (F(0), F(1))
    candidates = []
    rejected = []

    # At an interior maximum of xyz, Lagrange multipliers imply
    # that x,y,z take at most two distinct values. If t is repeated,
    # q = 2*s*t - 3*t^2.
    for branch in (-1, 1):
        t = div(add(scalar(s), mul(scalar(branch), root)), scalar(3))
        third = sub(scalar(s), mul(scalar(2), t))
        if sign(t) > 0 and sign(third) > 0:
            candidates.append((mul(mul(t, t), third), (t, t, third)))
        else:
            rejected.append({
                "repeated": text(t),
                "third": text(third),
                "reason": "not all coordinates are positive"
            })

    if not candidates:
        raise ArithmeticError("No positive maximizing candidate")

    rmax, values = candidates[0]
    for r, triple in candidates[1:]:
        if sign(sub(r, rmax)) > 0:
            rmax, values = r, triple

    x, y, z = values
    assert add(add(x, y), z) == scalar(s)
    assert add(add(mul(x, y), mul(x, z)), mul(y, z)) == scalar(q)
    assert sign(rmax) > 0

