import json

# Each occupied cell represents objects with membership (P, Q).
# Four cells suffice to enumerate every possible truth pattern.
cells = [(False, False), (False, True),
         (True, False), (True, True)]

def analyze(converse):
    signature = []
    countermodels = []
    for mask in range(1, 16):
        occupied = [cells[i] for i in range(4) if mask & (1 << i)]
        premise = any(p and not q for p, q in occupied)
        conclusion = any(
            (q and not p) if converse else (p and not q)
            for p, q in occupied
        )
        signature.append((premise, conclusion))
        if premise and not conclusion:
            countermodels.append(mask)
    return {
        "signature": signature,
        "valid": not countermodels,
        "countermodels": countermodels,
    }

# Original: some P are not Q -> some Q are not P.
# A, C, D reverse the two categories in the same way.
# B restates "some P are not Q" as "not all P are Q".
original = analyze(True)
options = {
    "A": analyze(True),
    "B": analyze(False),
    "C": analyze(True),
    "D": analyze(True),
}

different = [
    label for label, result in options.items()
    if result["signature"] != original["signature"]
]

answer = different[0] if len(different) == 1 else "UNSUPPORTED"
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "interpretation": "Which option does not follow the original inference pattern?",
        "original_valid": original["valid"],
        "option_validity": {
            label: result["valid"] for label, result in options.items()
        },
        "same_pattern": [
            label for label, result in options.items()
            if result["signature"] == original["signature"]
