M 0.0,0.0 L 0.0,14.80251
M -0.0,21.72644 L 0.0,16.81045
M -15.59808,14.80251 L -15.59808,21.72644
M -9.98277,8.80251 L 0.0,8.80251
M 9.07607,21.72644 L 9.07607,14.80251
M 5.35488,14.80251 L 0.0,14.80251
M -0.0,21.72644 L 9.07607,21.72644
M 0.0,14.80251 L -15.59808,14.80251
M -5.19615,11.80251 L 0.0,14.80251
M 0.0,8.80251 L -5.19615,11.80251
M -15.59808,21.72644 L -0.0,21.72644
M 9.07607,14.80251 L 9.07607,9.32558
M -15.59808,8.80251 L -9.98277,8.80251
M 9.07607,9.32558 L 9.07607,0.0
M 0.0,14.80251 L -0.0,21.72644
M 9.07607,14.80251 L 5.35488,14.80251
M -15.59808,14.80251 L -15.59808,13.48251 L -15.59808,8.80251
M 0.0,14.80251 L 9.07607,14.80251"""

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def orient(a, b, c):
    return cross(sub(b, a), sub(c, a))

def on_segment(p, a, b):
    return (orient(a, b, p) == 0
            and min(a[0], b[0]) <= p[0] <= max(a[0], b[0])
            and min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

segments = []
previous = None
for command, x, y in re.findall(r"([ML])\s+(-?[\d.]+),(-?[\d.]+)", svg):
    point = (F(x), F(y))
    if command == "L" and point != previous:
        segments.append((previous, point))
    previous = point

# Split every segment at every endpoint and intersection, including overlaps.
points = {p for segment in segments for p in segment}
for a, b in segments:
    r = sub(b, a)
    for c, d in segments:
        s = sub(d, c)
        denominator = cross(r, s)
        if denominator:
            t = cross(sub(c, a), s) / denominator
            u = cross(sub(c, a), r) / denominator
            if 0 <= t <= 1 and 0 <= u <= 1:
                points.add((a[0] + t * r[0], a[1] + t * r[1]))

vertices = sorted(points)
index = {p: i for i, p in enumerate(vertices)}
graph = defaultdict(set)
for a, b in segments:
    ordered = sorted(
        (p for p in points if on_segment(p, a, b)),
        key=lambda p: dot(sub(p, a), sub(b, a))
    )
    for p, q in zip(ordered, ordered[1:]):
        i, j = index[p], index[q]
        graph[i].add(j)
        graph[j].add(i)

# Exhaustively enumerate undirected simple cycles. A planarized graph cycle
# is a simple polygon; collinear subdivision vertices are not corners.
cycles = []
for start in range(len(vertices)):
    path = [start]
    used = {start}

    def search(v):
        for w in sorted(graph[v]):
            if w == start:
                if len(path) >= 3 and path[1] < path[-1]:
                    cycles.append(tuple(path))
            elif w > start and w not in used:
                used.add(w)
                path.append(w)
                search(w)
                path.pop()
                used.remove(w)

    search(start)

def corners(cycle):
    polygon = [vertices[i] for i in cycle]
    return [
        p for i, p in enumerate(polygon)
        if orient(polygon[i - 1], p, polygon[(i + 1) % len(polygon)]) != 0
    ]

def strictly_inside(p, polygon):
    if any(on_segment(p, a, b)
           for a, b in zip(polygon, polygon[1:] + polygon[:1])):
        return False
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
                inside = not inside
    return inside

def drawn_straight_segment(a, b):
    # Verify coverage of the entire candidate chord, not just its endpoints.
    direction = sub(b, a)
    denominator = dot(direction, direction)
    intervals = []
    for c, d in segments:
        if orient(a, b, c) == 0 and orient(a, b, d) == 0:
            lo, hi = sorted((dot(sub(c, a), direction) / denominator,
                             dot(sub(d, a), direction) / denominator))
            lo, hi = max(lo, F(0)), min(hi, F(1))
            if lo <= hi:
                intervals.append((lo, hi))
    reached = F(0)
    for lo, hi in sorted(intervals):
        if lo > reached:
            return False
        reached = max(reached, hi)
    return reached >= 1

def has_drawn_diagonal(polygon):
    n = len(polygon)
    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            a, b = polygon[i], polygon[j]
            if not drawn_straight_segment(a, b):
                continue
            # Split the chord at every boundary intersection and test
            # each open interval. An exterior chord is not a diagonal.
            r = sub(b, a)
            parameters = {F(0), F(1)}
            for c, d in zip(polygon, polygon[1:] + polygon[:1]):
                s = sub(d, c)
                den = cross(r, s)
                if den:
                    t = cross(sub(c, a), s) / den
                    u = cross(sub(c, a), r) / den
                    if 0 <= t <= 1 and 0 <= u <= 1:
                        parameters.add(t)
            ts = sorted(parameters)
            if all(strictly_inside(
                    (a[0] + ((lo + hi) / 2) * r[0],
                     a[1] + ((lo + hi) / 2) * r[1]), polygon)
                   for lo, hi in zip(ts, ts[1:])):
                return True
    return False

def close(a, b):
    # Used only for metric classifications affected by decimal rounding.
    return abs(float(a - b)) <= 1e-4 * max(1.0, abs(float(a)), abs(float(b)))

def perpendicular(a, b):
    return abs(float(dot(a, b))) <= 1e-5 * math.sqrt(float(dot(a, a) * dot(b, b)))

def regular(edges, turns):
    if not (all(t > 0 for t in turns) or all(t < 0 for t in turns)):
        return False
    lengths = [dot(e, e) for e in edges]
    adjacent_dots = [dot(edges[i - 1], edges[i]) for i in range(len(edges))]
    return (all(close(x, lengths[0]) for x in lengths)
            and all(close(x, adjacent_dots[0]) for x in adjacent_dots))

witnesses = {}
for cycle in cycles:
    polygon = corners(cycle)
    n = len(polygon)
    if n < 3:
        continue
    edges = [sub(polygon[(i + 1) % n], polygon[i]) for i in range(n)]
    turns = [cross(edges[i - 1], edges[i]) for i in range(n)]
    convex = all(t > 0 for t in turns) or all(t < 0 for t in turns)
    kinds = set()

    if n == 3:
        kinds.add(4 if any(perpendicular(edges[i - 1], edges[i])
                           for i in range(n)) else 3)
    elif not has_drawn_diagonal(polygon):
        if n == 4 and convex:
            parallel_pairs = (
                int(cross(edges[0], edges[2]) == 0)
                + int(cross(edges[1], edges[3]) == 0)
            )
            rectangle = all(perpendicular(edges[i - 1], edges[i])
                            for i in range(n))
            if rectangle:
                lengths = [dot(e, e) for e in edges]
                kinds.add(2 if all(close(x, lengths[0]) for x in lengths) else 1)
            elif parallel_pairs == 2:
                kinds.add(5)
            elif parallel_pairs == 1:
                kinds.add(6)
        elif n == 5:
            kinds.add(9 if regular(edges, turns) else (7 if convex else 8))
        elif n == 6 and regular(edges, turns):
            kinds.add(10)

    for kind in kinds:
        witnesses.setdefault(kind, polygon)

expected = set(witnesses)
options = {
    "A": {1, 8}, "B": set(), "C": {2}, "D": {5, 9},
    "E": {8}, "F": {1, 8, 5}, "G": {1, 8, 3, 4},
    "H": {1}, "I": {1, 5}, "J": {1, 8, 4, 9},
    "K": {1, 8, 6}, "L": {8, 3, 7}, "M": {2, 3},
    "N": {1, 7}, "O": {8, 2, 6, 10}, "P": {1, 8, 2},
}
