import itertools
import json

countries = ("South Korea", "France", "Britain", "Germany")
options = {
    "A": ("Britain", "Germany", "South Korea", "France"),
    "B": ("France", "Britain", "Germany", "South Korea"),
    "C": ("Germany", "Britain", "France", "South Korea"),
    "D": ("Germany", "Britain", "South Korea", "France"),
}

# Everyone speaks their own country's language. Enumerate all possible
# additional languages rather than assuming unmentioned ones are absent.
def language_sets(required):
    optional = [c for c in countries if c not in required]
    for mask in range(1 << len(optional)):
        yield frozenset(required) | frozenset(
            c for i, c in enumerate(optional) if mask & (1 << i)
        )

solutions = []
for french in language_sets({"France", "Germany"}):
    for british in language_sets({"Britain", "South Korea"}):
        spoken = {
            "South Korea": frozenset({"South Korea"}),
            "France": french,
            "Britain": british,
            "Germany": frozenset(countries),
        }
        for order in itertools.permutations(countries):
            position = {country: i for i, country in enumerate(order)}
            if position["South Korea"] <= position["Germany"]:
                continue

            def communicating_neighbors(country):
                i = position[country]
                return sum(
                    bool(spoken[country] & spoken[order[j]])
                    for j in (i - 1, i + 1)
                    if 0 <= j < 4
                )

            if communicating_neighbors("South Korea") != 0:
                continue
            if communicating_neighbors("France") != 0:
                continue
            if communicating_neighbors("Britain") != 1:
                continue
            solutions.append(order)

orders = sorted(set(solutions))
matching = [
    letter for letter, order in options.items()
    if orders == [order]
]

if len(matching) == 1:
    letter = matching[0]
    answer = letter + ". " + ", ".join(options[letter])
else:
    answer = "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "valid_orders": [list(order) for order in orders],
        "satisfying_language_and_room_models": len(solutions)
    }
}, separators=(",", ":")))
